/**
 * Generates src/abis.ts from Foundry build output (contracts/out). Run after `forge build`:
 *   npm run gen:abis
 * The generated file is committed so the backend builds without Foundry; CI regenerates it and
 * fails if it differs, so ABIs can never drift from the audited contracts.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const OUT = fileURLToPath(new URL("../../../../contracts/out/", import.meta.url));
const TARGET = fileURLToPath(new URL("../src/abis.ts", import.meta.url));

// [export name, artifact "File.sol/Contract.json"]
const ARTIFACTS: [string, string][] = [
  ["issuanceGuardAbi", "IssuanceGuard.sol/IssuanceGuard.json"],
  ["pauseGuardAbi", "PauseGuard.sol/PauseGuard.json"],
  ["freezeGuardAbi", "FreezeGuard.sol/FreezeGuard.json"],
  ["recoveryGuardAbi", "RecoveryGuard.sol/RecoveryGuard.json"],
  ["registrarGuardAbi", "RegistrarGuard.sol/RegistrarGuard.json"],
  ["distributionRegistryAbi", "DistributionRegistry.sol/DistributionRegistry.json"],
  ["documentRegistryAbi", "DocumentRegistry.sol/DocumentRegistry.json"],
  ["stateAnchorAbi", "StateAnchor.sol/StateAnchor.json"],
  ["timelockAbi", "TimelockController.sol/TimelockController.json"],
  ["tokenAbi", "Token.sol/Token.json"],
  ["identityRegistryAbi", "IdentityRegistry.sol/IdentityRegistry.json"],
  ["identityAbi", "Identity.sol/Identity.json"],
  ["idFactoryAbi", "IdFactory.sol/IdFactory.json"],
];

let out =
  "// GENERATED by packages/contracts/scripts/gen-abis.ts from contracts/out. Do not edit by hand.\n" +
  "/* eslint-disable */\n";
for (const [name, file] of ARTIFACTS) {
  // Fixed artifact list above; build-time script only.
  // eslint-disable-next-line security/detect-non-literal-fs-filename
  const artifact = JSON.parse(readFileSync(OUT + file, "utf8")) as { abi: unknown };
  out += `\nexport const ${name} = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
}
// eslint-disable-next-line security/detect-non-literal-fs-filename
writeFileSync(TARGET, out);
console.log(`Wrote ${ARTIFACTS.length} ABIs to ${TARGET}`);
